  "the public input is not whole words": "المدخل العام ليس كلمات كاملة",
  "the RAND fee: {reason}": "رسوم RAND: {reason}",
  "The Rand node this wallet reads from and submits to.": "عقدة Rand التي تقرأ منها هذه المحفظة وترسل إليها.",
  "The Rand node this wallet reads from and submits to. Clear this field to go back to the default nodes.": "عقدة Rand التي تقرأ منها هذه المحفظة وترسل إليها. امسح هذا الحقل للعودة إلى العقد الافتراضية.",
  "the RAND notes hold {held}, but fee + RAND deposit is {need}": "سندات RAND تحمل {held}، لكن الرسوم + إيداع RAND = {need}",
  "the RAND notes hold {held}, but the fee is {fee}": "سندات RAND تحمل {held}، لكن الرسوم {fee}",
  "the RandProtocol provers ({n} machines run by the validators; each one that proves a send sees that wallet's viewing key)": { zero: "مُثبِتات RandProtocol ({n} أجهزة يشغّلها المدقّقون، وكل مُثبِت يُثبت إرسالًا يرى مفتاح العرض لتلك المحفظة)", one: "مُثبِتات RandProtocol ({n} جهاز يشغّلها المدقّقون، وكل مُثبِت يُثبت إرسالًا يرى مفتاح العرض لتلك المحفظة)", two: "مُثبِتات RandProtocol ({n} جهازان يشغّلها المدقّقون، وكل مُثبِت يُثبت إرسالًا يرى مفتاح العرض لتلك المحفظة)", few: "مُثبِتات RandProtocol ({n} أجهزة يشغّلها المدقّقون، وكل مُثبِت يُثبت إرسالًا يرى مفتاح العرض لتلك المحفظة)", many: "مُثبِتات RandProtocol ({n} جهازًا يشغّلها المدقّقون، وكل مُثبِت يُثبت إرسالًا يرى مفتاح العرض لتلك المحفظة)", other: "مُثبِتات RandProtocol ({n} جهاز يشغّلها المدقّقون، وكل مُثبِت يُثبت إرسالًا يرى مفتاح العرض لتلك المحفظة)" },
  "the RandProtocol provers (machines run by the validators; each one that proves a send sees that wallet's viewing key)": "مُثبِتات RandProtocol (أجهزة يشغّلها المدقّقون، وكل مُثبِت يُثبت إرسالًا يرى مفتاح العرض لتلك المحفظة)",
  "The RandProtocol provers are busy": "مُثبِتات RandProtocol مشغولة",
  "The RandProtocol provers can read your history": "تستطيع مُثبِتات RandProtocol قراءة سجلك",
  "The RandProtocol provers cannot be reached": "تعذّر الوصول إلى مُثبِتات RandProtocol",
  "The RandProtocol provers: {n} machine run by the validators, with its own key, used until you choose another.": { zero: "مُثبِتات RandProtocol: {n} أجهزة يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", one: "مُثبِتات RandProtocol: {n} جهاز يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", two: "مُثبِتات RandProtocol: {n} جهازان يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", few: "مُثبِتات RandProtocol: {n} أجهزة يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", many: "مُثبِتات RandProtocol: {n} جهازًا يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", other: "مُثبِتات RandProtocol: {n} جهاز يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها." },
  "The RandProtocol provers: {n} machines run by the validators, each with its own key, used until you choose another.": { zero: "مُثبِتات RandProtocol: {n} أجهزة يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", one: "مُثبِتات RandProtocol: {n} جهاز يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", two: "مُثبِتات RandProtocol: {n} جهازان يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", few: "مُثبِتات RandProtocol: {n} أجهزة يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", many: "مُثبِتات RandProtocol: {n} جهازًا يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.", other: "مُثبِتات RandProtocol: {n} جهاز يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها." },
  "The RandProtocol provers: machines run by the validators, each with its own key, used until you choose another.": "مُثبِتات RandProtocol: أجهزة يشغّلها المدقّقون، لكلٍّ منها مفتاحه، وتُستخدم حتى تختار غيرها.",
  "The randprover: link your prover shows. It carries a secret — paste it here and nowhere else.": "رابط randprover: الذي يعرضه مُثبِتك. يحمل سرًّا — الصقه هنا ولا تلصقه في أي مكان آخر.",
  "the relayer fee {fee} is more than the {amount} being burned": "رسوم المُرحِّل {fee} أكثر من المبلغ المحروق {amount}",
  "The relayer fee cannot be more than the amount being withdrawn.": "لا يمكن أن تزيد رسوم المُرحِّل على المبلغ المسحوب.",
  "The relayer fee is more than the amount being withdrawn.": "رسوم المُرحِّل أكثر من المبلغ المسحوب.",
